/**
 * One mock for every Release Relay callout: Tooling API, GitHub, GitLab, Bitbucket and Azure DevOps.
 */
@IsTest
public class RlyCalloutMock implements HttpCalloutMock {

    public Boolean failDispatch = false;
    /** With failDispatch: refuse the retry without options too (otherwise only the options are refused). */
    public Boolean failDispatchAlways = false;
    public String runTitle = 'Release Relay REL-00000 (org)';
    public String runConclusion = 'success';
    public Boolean prMerged = false;
    public Boolean noPr = false;
    public Set<String> existingBranches = new Set<String>{ 'sit', 'uat', 'main', 'feature/existing-work' };
    /** Step (scan, validate, merge, deploy) to the result JSON the workflow would have written. */
    public Map<String, String> results = new Map<String, String>();
    public Integer dispatchCount = 0;
    /** Zip (base64) a Metadata API retrieve returns. */
    public String zipBase64 = '';
    public Boolean deploySucceeds = true;

    /** A result as the workflow writes it, finished now. */
    public static String result(String status, String extra) {
        return '{"status":"' + status + '","finishedAt":"' + Datetime.now().formatGmt('yyyy-MM-dd\'T\'HH:mm:ss.SSS\'Z\'') + '"'
            + (String.isBlank(extra) ? '' : ',' + extra) + '}';
    }

    public HttpResponse respond(HttpRequest req) {
        String url = req.getEndpoint();
        String decoded = EncodingUtil.urlDecode(url, 'UTF-8');
        HttpResponse res = new HttpResponse();
        res.setHeader('Content-Type', 'application/json');
        res.setStatusCode(200);

        if (url.startsWith('callout:RLY_GitLab')) {
            return gitlab(req, decoded, res);
        } else if (url.startsWith('callout:RLY_Bitbucket')) {
            return bitbucket(req, decoded, res);
        } else if (url.startsWith('callout:RLY_AzureDevOps')) {
            return azure(req, decoded, res);
        } else if (url.contains('/services/Soap/m/')) {
            return soap(req, res);
        }

        if (url.contains('/services/data/v62.0/query/?q=')) {
            res.setBody(tooling(decoded));
            return res;
        }
        if (url.contains('/git/ref/heads/')) {
            res.setBody('{"ref":"refs/heads/sit","object":{"sha":"abc123","type":"commit"}}');
            return res;
        }
        if (url.contains('/git/refs') && req.getMethod() == 'POST') {
            res.setStatusCode(201);
            res.setBody('{"ref":"refs/heads/new","object":{"sha":"abc123"}}');
            return res;
        }
        if (url.contains('/contents/') && req.getMethod() == 'PUT') {
            res.setStatusCode(201);
            res.setBody('{"content":{"sha":"new-sha"},"commit":{"sha":"c1"}}');
            return res;
        }
        if (url.contains('/contents/force-app/main/default/classes/') && req.getHeader('Accept') == 'application/vnd.github+json') {
            res.setBody('{"type":"file","sha":"old-sha","name":"ProviderSearch.cls"}');
            return res;
        }

        if (url.contains('/tooling/query/01g')) {
            res.setBody('{"done":true,"records":[{"Name":"Another"}]}');
        } else if (url.contains('/tooling/query')) {
            res.setBody(tooling(decoded));
        } else if (url.contains('recursive=1')) {
            res.setBody('{"truncated":false,"tree":['
                + '{"path":"force-app/main/default/classes/ProviderSearch.cls","type":"blob","sha":"b1"},'
                + '{"path":"force-app/main/default/classes/ProviderSearch.cls-meta.xml","type":"blob","sha":"b2"},'
                + '{"path":"force-app/main/default/objects/Account/fields/Region__c.field-meta.xml","type":"blob","sha":"b5"},'
                + '{"path":"force-app/main/default/labels/CustomLabels.labels-meta.xml","type":"blob","sha":"b6"}]}');
        } else if (url.contains('/git/trees/sha-default')) {
            res.setBody('{"tree":[{"path":"classes","type":"tree","sha":"sha-classes"},{"path":"lwc","type":"tree","sha":"sha-lwc"}]}');
        } else if (url.contains('/git/trees/')) {
            res.setBody(url.contains('sha-lwc')
                ? '{"tree":[{"path":"providerSearch","type":"tree","sha":"t1"},{"path":"oldCmp","type":"tree","sha":"t2"}]}'
                : '{"tree":[{"path":"ProviderSearch.cls","type":"blob","sha":"b1"},{"path":"ProviderSearch.cls-meta.xml","type":"blob","sha":"b2"},'
                    + '{"path":"OldClass.cls","type":"blob","sha":"b3"},{"path":"Another.cls","type":"blob","sha":"b4"}]}');
        } else if (decoded.contains('/contents/results/')) {
            String step = decoded.substringAfterLast('/').substringBefore('.json');
            if (results.containsKey(step)) {
                res.setBody(results.get(step));
            } else {
                res.setStatusCode(404);
                res.setBody('{"message":"Not Found"}');
            }
        } else if (url.contains('/contents/')) {
            if (decoded.contains('.github/workflows/')) {
                res.setBody('name: Release Relay');
            } else if (decoded.contains('/contents/force-app/main?')) {
                res.setBody('[{"name":"default","type":"dir","sha":"sha-default"}]');
            } else if (decoded.contains('/contents/force-app/main/default?')) {
                res.setBody('[{"name":"classes","type":"dir","sha":"sha-classes"},{"name":"lwc","type":"dir","sha":"sha-lwc"},'
                    + '{"name":"README.md","type":"file","sha":"x"}]');
            } else if (decoded.contains('.html')) {
                res.setStatusCode(404);
                res.setBody('{"message":"Not Found"}');
            } else {
                res.setBody('public with sharing class ProviderSearch {\n}');
            }
        } else if (url.contains('/branches?')) {
            res.setBody('[{"name":"main"},{"name":"sit"},{"name":"feature/existing-work"},{"name":"Random-Branch"}]');
        } else if (url.contains('/branches/')) {
            String branch = EncodingUtil.urlDecode(url.substringAfter('/branches/'), 'UTF-8');
            if (existingBranches.contains(branch)) {
                res.setBody('{"name":"' + branch + '"}');
            } else {
                res.setStatusCode(404);
                res.setBody('{"message":"Branch not found"}');
            }
        } else if (url.contains('/compare/')) {
            res.setBody('{"ahead_by":2,"behind_by":0,"html_url":"https://github.com/acme/sfdx/compare/sit...feature/existing-work",'
                + '"files":[{"status":"modified","filename":"force-app/main/default/classes/ProviderSearch.cls"}]}');
        } else if (url.contains('/dispatches')) {
            dispatchCount++;
            Boolean refuse = failDispatch && (failDispatchAlways || String.valueOf(req.getBody()).contains('"options"'));
            res.setStatusCode(refuse ? 422 : 204);
            res.setBody(refuse ? '{"message":"Unexpected inputs provided: [\"options\"]"}' : '');
        } else if (url.contains('/runs')) {
            res.setBody('{"workflow_runs":[{"id":555,"status":"completed","conclusion":"' + runConclusion + '",'
                + '"display_title":"' + runTitle + '","html_url":"https://github.com/acme/sfdx/actions/runs/555",'
                + '"created_at":"' + Datetime.now().formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'') + '"}]}');
        } else if (url.contains('/files?')) {
            res.setBody('[{"filename":"force-app/main/default/classes/ProviderSearch.cls","status":"modified","additions":2,"deletions":1,'
                + '"patch":"@@ -1,2 +1,3 @@\\n public class ProviderSearch {\\n-  // old\\n+  // new\\n+  // more\\n }"}]');
        } else if (url.contains('/pulls') && noPr) {
            res.setBody('[]');
        } else if (url.contains('/pulls')) {
            res.setBody('[{"number":42,"html_url":"https://github.com/acme/sfdx/pull/42","state":"' + (prMerged ? 'closed' : 'open')
                + '","merged_at":' + (prMerged ? '"2026-10-27T10:00:00Z"' : 'null') + '}]');
        } else {
            res.setStatusCode(404);
            res.setBody('{}');
        }
        return res;
    }

    private HttpResponse gitlab(HttpRequest req, String u, HttpResponse res) {
        if (u.contains('/repository/branches/')) {
            res.setStatusCode(existingBranches.contains(u.substringAfter('/repository/branches/')) ? 200 : 404);
            res.setBody('{}');
        } else if (u.contains('/repository/branches?')) {
            res.setBody('[{"name":"sit"},{"name":"feature/existing-work"}]');
        } else if (u.contains('/repository/files/')) {
            res.setBody('public class ProviderSearch {}');
        } else if (u.contains('/repository/tree?')) {
            res.setBody(u.contains('path=force-app/main/default/classes')
                ? '[{"name":"ProviderSearch.cls","type":"blob"},{"name":"OldClass.cls","type":"blob"}]'
                : '[{"name":"classes","type":"tree"},{"name":"lwc","type":"tree"}]');
        } else if (u.contains('/repository/compare')) {
            res.setBody('{"commits":[{"id":"c1"}],"diffs":[{"new_path":"force-app/main/default/classes/A.cls","new_file":true}],"web_url":"https://gitlab.com/x/-/compare"}');
        } else if (req.getMethod() == 'POST' && u.endsWith('/pipeline')) {
            dispatchCount++;
            res.setStatusCode(failDispatch ? 400 : 201);
            res.setBody(failDispatch ? '{"message":"bad"}' : '{"id":900,"web_url":"https://gitlab.com/x/-/pipelines/900"}');
        } else if (u.contains('/pipelines/')) {
            res.setBody('{"status":"success","web_url":"https://gitlab.com/x/-/pipelines/900","created_at":"2030-01-01T00:00:00Z"}');
        } else if (u.contains('/merge_requests?')) {
            res.setBody('[{"iid":5,"web_url":"https://gitlab.com/x/-/merge_requests/5","state":"' + (prMerged ? 'merged' : 'opened') + '"}]');
        } else if (u.contains('/merge_requests/5/diffs')) {
            res.setBody('[{"new_path":"force-app/main/default/classes/A.cls","diff":"@@ -1 +1 @@\\n-a\\n+b","new_file":false}]');
        } else {
            res.setStatusCode(404);
            res.setBody('{}');
        }
        return res;
    }

    private HttpResponse bitbucket(HttpRequest req, String u, HttpResponse res) {
        if (u.contains('/refs/branches/')) {
            res.setStatusCode(existingBranches.contains(u.substringAfter('/refs/branches/')) ? 200 : 404);
            res.setBody('{}');
        } else if (u.contains('/refs/branches?')) {
            res.setBody('{"values":[{"name":"sit"},{"name":"feature/existing-work"}]}');
        } else if (u.contains('/src/') && u.contains('/?pagelen')) {
            res.setBody(u.contains('/classes/')
                ? '{"values":[{"path":"force-app/main/default/classes/ProviderSearch.cls","type":"commit_file"}]}'
                : '{"values":[{"path":"force-app/main/default/classes","type":"commit_directory"}]}');
        } else if (u.contains('/src/')) {
            res.setBody('public class ProviderSearch {}');
        } else if (u.contains('/pullrequests/9/diffstat') || u.contains('/diffstat/')) {
            res.setBody('{"values":[{"status":"modified","lines_added":1,"lines_removed":1,"new":{"path":"force-app/main/default/classes/A.cls"}}]}');
        } else if (u.contains('/pullrequests/9/diff')) {
            res.setStatusCode(302);
            res.setHeader('Location', 'https://api.bitbucket.org/2.0/repositories/ws/repo/diff/abc');
        } else if (u.contains('/repositories/ws/repo/diff/abc')) {
            res.setBody('diff --git a/force-app/main/default/classes/A.cls b/force-app/main/default/classes/A.cls\nindex 1..2\n--- a/x\n+++ b/x\n@@ -1 +1 @@\n-a\n+b\n');
        } else if (req.getMethod() == 'POST' && u.endsWith('/pipelines/')) {
            dispatchCount++;
            res.setStatusCode(201);
            res.setBody('{"uuid":"{u1}","build_number":7}');
        } else if (u.contains('/pipelines/')) {
            res.setBody('{"build_number":7,"created_on":"2030-01-01T00:00:00Z","state":{"name":"COMPLETED","result":{"name":"SUCCESSFUL"}}}');
        } else if (u.contains('/pullrequests?')) {
            res.setBody('{"values":[{"id":9,"state":"OPEN","links":{"html":{"href":"https://bitbucket.org/ws/repo/pull-requests/9"}}}]}');
        } else {
            res.setStatusCode(404);
            res.setBody('{}');
        }
        return res;
    }

    private HttpResponse azure(HttpRequest req, String u, HttpResponse res) {
        if (u.contains('/refs?filter=heads/&')) {
            res.setBody('{"value":[{"name":"refs/heads/sit"},{"name":"refs/heads/feature/existing-work"}]}');
        } else if (u.contains('/refs?filter=')) {
            String b = u.substringAfter('/refs?filter=heads/').substringBefore('&');
            res.setBody(existingBranches.contains(b) ? '{"value":[{"name":"refs/heads/' + b + '"}]}' : '{"value":[]}');
        } else if (u.contains('/items?scopePath=')) {
            res.setBody(u.contains('scopePath=/force-app/main/default/classes')
                ? '{"value":[{"path":"/force-app/main/default/classes","isFolder":true},{"path":"/force-app/main/default/classes/ProviderSearch.cls","isFolder":false}]}'
                : '{"value":[{"path":"/force-app/main/default","isFolder":true},{"path":"/force-app/main/default/classes","isFolder":true}]}');
        } else if (u.contains('/items?path=')) {
            res.setBody('public class ProviderSearch {}');
        } else if (u.contains('/diffs/commits')) {
            res.setBody('{"aheadCount":1,"behindCount":0,"changes":[{"item":{"path":"/force-app/main/default/classes/A.cls"},"changeType":"edit"}]}');
        } else if (req.getMethod() == 'POST' && u.contains('/_apis/pipelines/')) {
            dispatchCount++;
            res.setBody('{"id":77,"_links":{"web":{"href":"https://dev.azure.com/o/p/_build/results?buildId=77"}}}');
        } else if (u.contains('/_apis/pipelines/')) {
            res.setBody('{"id":77,"state":"completed","result":"succeeded","createdDate":"2030-01-01T00:00:00Z","_links":{"web":{"href":"https://dev.azure.com/x"}}}');
        } else if (u.contains('/pullrequests?')) {
            res.setBody('{"value":[{"pullRequestId":4,"status":"active"}]}');
        } else if (u.contains('/pullrequests/4')) {
            res.setBody('{"pullRequestId":4,"lastMergeSourceCommit":{"commitId":"' + 'a'.repeat(40) + '"},"lastMergeTargetCommit":{"commitId":"' + 'b'.repeat(40) + '"}}');
        } else {
            res.setStatusCode(404);
            res.setBody('{}');
        }
        return res;
    }

    private HttpResponse soap(HttpRequest req, HttpResponse res) {
        String body = req.getBody();
        res.setHeader('Content-Type', 'text/xml');
        String soapInner;
        if (body.contains('checkRetrieveStatus')) {
            soapInner = '<checkRetrieveStatusResponse><result><done>true</done><id>09S1</id><status>Succeeded</status><success>true</success>'
                + '<zipFile>' + zipBase64 + '</zipFile></result></checkRetrieveStatusResponse>';
        } else if (body.contains('<met:retrieve>')) {
            soapInner = '<retrieveResponse><result><done>false</done><id>09S1</id></result></retrieveResponse>';
        } else if (body.contains('deployRecentValidation')) {
            soapInner = '<deployRecentValidationResponse><result>0Af3</result></deployRecentValidationResponse>';
        } else if (body.contains('checkDeployStatus')) {
            soapInner = '<checkDeployStatusResponse><result><done>true</done><id>0Af1</id><status>' + (deploySucceeds ? 'Succeeded' : 'Failed') + '</status>'
                + '<success>' + deploySucceeds + '</success><details>'
                + (deploySucceeds ? '' : '<componentFailures><componentType>ApexClass</componentType><fullName>ProviderSearch</fullName><problem>Bad</problem><lineNumber>3</lineNumber></componentFailures>')
                + '<runTestResult><numTestsRun>2</numTestsRun></runTestResult></details></result></checkDeployStatusResponse>';
        } else {
            soapInner = '<deployResponse><result><done>false</done><id>0Af1</id></result></deployResponse>';
        }
        res.setBody('<?xml version="1.0" encoding="UTF-8"?><soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" '
            + 'xmlns="http://soap.sforce.com/2006/04/metadata"><soapenv:Body>' + soapInner + '</soapenv:Body></soapenv:Envelope>');
        return res;
    }

    private String tooling(String q) {
        if (q.contains('LightningComponentResource')) {
            return '{"done":true,"records":[{"FilePath":"lwc/providerSearch/providerSearch.js","Source":"export default class A {}"},'
                + '{"FilePath":"lwc/providerSearch/providerSearch.html","Source":"<template></template>"}]}';
        }
        if (q.contains('FROM EntityDefinition')) {
            return '{"done":true,"records":[{"DurableId":"01Ixx0000000001","QualifiedApiName":"Invoice__c"}]}';
        }
        if (q.contains('FROM CustomField')) {
            return '{"done":true,"records":[{"DeveloperName":"Amount","TableEnumOrId":"01Ixx0000000001AAA",'
                + '"LastModifiedDate":"2026-10-22T16:42:11.000+0000","LastModifiedById":"' + UserInfo.getUserId() + '",'
                + '"LastModifiedBy":{"Name":"Test User"}},{"DeveloperName":"Region","TableEnumOrId":"Account",'
                + '"LastModifiedDate":"2026-10-22T16:42:11.000+0000","LastModifiedById":"' + UserInfo.getUserId() + '",'
                + '"LastModifiedBy":{"Name":"Test User"}}]}';
        }
        if (q.contains('SELECT Body')) {
            return '{"done":true,"records":[{"Body":"public with sharing class ProviderSearch {\\n  // new\\n}"}]}';
        }
        if (q.contains('SELECT Markup')) {
            return '{"done":true,"records":[{"Markup":"<apex:page></apex:page>"}]}';
        }
        if (q.contains('AuraDefinition ')) {
            return '{"done":true,"records":[{"DefType":"COMPONENT","Source":"<aura:component/>"}]}';
        }
        if (!q.contains('LastModifiedDate')) {
            // Org-wide name lists used to find deletions; the Apex list spans two pages.
            if (q.contains('FROM ApexClass')) {
                return '{"done":false,"nextRecordsUrl":"/services/data/v62.0/tooling/query/01gXX-2000","records":[{"Name":"ProviderSearch"}]}';
            }
            return '{"done":true,"records":[{"Name":"ProviderSearch","DeveloperName":"providerSearch"}]}';
        }
        return '{"done":true,"records":[{"Name":"ProviderSearch","DeveloperName":"providerSearch",'
            + '"LastModifiedDate":"2026-10-22T16:42:11.000+0000","LastModifiedById":"' + UserInfo.getUserId() + '",'
            + '"LastModifiedBy":{"Name":"Test User"}}]}';
    }
}
